KG42.register("nodes-373379e692ca0a6350efb44d",{"id":"COMP-76d88cced26fe0a5","code":"PRC033","label":"Wholesale-price information provision and uniform marginal-total-cost pricing","definition":"This unit contains two types of prices: information used for iteration, p^t(Q)=a^tQ+b^t; and the uniform customer rate, π^{*,t}=C'^t(Q*)=2a^tQ*+b^t, where Q*=Σ_i x_{i,Tot}^{*,t} is the welfare-optimal total energy use.","layer":"L6","template_code":"JOC","concept_id":"coordination.price_signal","concept_ids":["coordination.price_signal"],"identity_dimensions":{"identity_fields":["Object: two price objects, the wholesale price function and the uniform customer rate","Core relation: the wholesale function provides price information; the customer rate is determined by the marginal total cost at the optimum","Output: wholesale price information and the customer rate commonly applicable in each time period"]},"exclusions":["The wholesale function coefficients are predetermined by the utility and vary by time period","Wholesale price information is used for iteration together with the aggregate energy use of other customers","The uniform rate is used for dispatch and billing, and when it is determined, only the welfare objective is considered"],"members":[{"id":"38-bidirectional_ev_trading::v141-c-R001::V::coordination.price_signal","rule_id":"v141-c-R001","market_meaning":"Wholesale price-function information provides an input to customers' sequential social-welfare scheduling updates. The aggregator can broadcast that information together with other customers' aggregate energy consumption. Scope: Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i. Condition: At each iteration; the information can be broadcast at the beginning of the iteration. The common-linear-rate distributed formulation represents the collaborative social-welfare-optimal schedule as a collection of customer-optimal schedules at the specified rates. Scope: Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. Condition: Electricity rates equal marginal total cost evaluated at the social-welfare-optimal aggregate consumption, as specified in (9). Collaborative scheduling maximizes the sum of all customers' utilities minus the total cost charged to the aggregator, subject to each customer's feasible scheduling set satisfying conditions (1), (2), (3), and (5). Scope: Collaborative power system, all customers, over the scheduling interval. Condition: All customers are willing to cooperate.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Collaborative power system, all customers, over the scheduling interval. | Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. | Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E12","v141-b-g01-E13","v141-b-g01-E14","v141-b-g02-e04"]},"constraint_refs":["38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C001","38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C002"],"decision_anchor":"clearing.social_welfare","source_rule_sha256":"99d94280c77d2e63e3f40c3714f72118aa2227f73ec9a54b8a4c1392f400d7cd","paper":"38-bidirectional_ev_trading","rule_ref":"38-bidirectional_ev_trading::v141-c-R001","node_id":"coordination.price_signal","function":"coordination.price_signal","unit_id":"38-bidirectional_ev_trading::M01::coordination.price_signal","mechanism_id":"M01","anchor":false},{"id":"38-bidirectional_ev_trading::v141-c-R003::V::coordination.price_signal","rule_id":"v141-c-R003","market_meaning":"The aggregator sets and applies electricity rates to coordinate customers' decentralized, utility-maximizing energy schedules. Scope: Collaborative distributed energy scheduling under the linear billing scheme represented by problems P2_i. The coordinating electricity rates are identical across customers and are determined solely to maximize social welfare, without considering allocation of total cost between customers and the aggregator. Scope: Collaborative linear billing with optimal electricity rates. Each customer's distributed scheduling iteration needs only the wholesale price function and the sum of other customers' energy consumption for every time-slot. Scope: Each iteration of the collaborative Gauss-Seidel distributed scheduling algorithm.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Collaborative distributed energy scheduling under the linear billing scheme represented by problems P2_i. | Collaborative linear billing with optimal electricity rates. | Each iteration of the collaborative Gauss-Seidel distributed scheduling algorithm.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E14","v141-b-g01-E16","v141-b-g02-e04"]},"constraint_refs":["38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C001","38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C002","38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C003"],"decision_anchor":"coordination.price_signal","source_rule_sha256":"b4b4026b6aad73e4914556f866f94bbb582159c533b07a51b37ed023e5beccd9","paper":"38-bidirectional_ev_trading","rule_ref":"38-bidirectional_ev_trading::v141-c-R003","node_id":"coordination.price_signal","function":"coordination.price_signal","unit_id":"38-bidirectional_ev_trading::M01::coordination.price_signal","mechanism_id":"M01","anchor":true},{"id":"38-bidirectional_ev_trading::v141-c-R005::V::coordination.price_signal","rule_id":"v141-c-R005","market_meaning":"The coordinating aggregator charges each customer an electricity bill for each time-slot. Scope: Customer billing in the collaborative distributed energy-scheduling framework. The electricity-rate signal coordinating distributed customer scheduling supplies the rate used to calculate customer bills. Scope: Customer bills under the collaborative linear billing scheme. Condition: The optimal linear electricity rates of problem P2_i are applied. The aggregator has an obligation to pay the utility company its electricity procurement cost. Scope: The aggregator's wholesale electricity procurement supporting the collaborative customer system. The sum of customer bills is greater than or equal to the total cost payable by the aggregator to the utility company. Scope: Aggregate customer bills and the aggregator's utility-company cost under collaborative linear billing. Condition: Bills are calculated using the linear rate bar-pi* in problem P2_i.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Aggregate customer bills and the aggregator's utility-company cost under collaborative linear billing. | Customer billing in the collaborative distributed energy-scheduling framework. | Customer bills under the collaborative linear billing scheme. | The aggregator's wholesale electricity procurement supporting the collaborative customer system.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E01","v141-b-g01-E14","v141-b-g01-E15","v141-b-g02-e04"]},"constraint_refs":["38-bidirectional_ev_trading::v141-c-R005::v141-c-R005-C002"],"decision_anchor":"settlement.payment","source_rule_sha256":"e1fa878d9ee1010543318756811ec7525744882978a94e702f9adaba64cf5852","paper":"38-bidirectional_ev_trading","rule_ref":"38-bidirectional_ev_trading::v141-c-R005","node_id":"coordination.price_signal","function":"coordination.price_signal","unit_id":"38-bidirectional_ev_trading::M01::coordination.price_signal","mechanism_id":"M01","anchor":false}],"paper_ids":["38-bidirectional_ev_trading"],"evidence":[{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-54c42059a7-p04-c1r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"cooperate to maximize the social welfare of the system, which anis deﬁned as the sum of all customer","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"In this section, we study the energy scheduling problem for a collaborative system, where all customers are willing to cooperate to maximize the social welfare of the system, which is defined as the sum of all customers' utilities minus the total cost charged to the aggregator. The resulting social welfare serves an upper bound on social welfare obtained using any feasible approaches. We first consider the following social welfare maximization problem: P: \\max_{\\bar{x}} \\sum_{t\\in T}\\sum_{i\\in I}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^t) s.t. \\bar{x}_i\\in X_i, \\forall i\\in I, where X_i represents the feasible set of customer i's energy scheduling which is defined as a set of \\bar{x}_i's that satisfy conditions in (1),(2),(3), and (5). It can be easily shown that problem P is convex programming. Moreover, the objective function is strictly concave with respect to \\bar{x}_i, the scheduling decision of any customer i, when the other customers' scheduling decisions, \\bar{x}_{-i}=[\\bar{x}_{i'}]_{i'\\ne i}, are fixed. Due to these properties of problem P, we can use the Gauss-Seidel method to solve it [22].","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R001","quote":"In this section, we study the energy scheduling problem for a collaborative system, where all customers are willing to cooperate to maximize the social welfare of the system, which is defined as the sum of all customers' utilities minus the total cost charged to the aggregator. The resulting social welfare serves an upper bound on social welfare obtained using any feasible approaches. We first consider the following social welfare maximization problem: P: \\max_{\\bar{x}} \\sum_{t\\in T}\\sum_{i\\in I}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^t) s.t. \\bar{x}_i\\in X_i, \\forall i\\in I, where X_i represents the feasible set of customer i's energy scheduling which is defined as a set of \\bar{x}_i's that satisfy conditions in (1),(2),(3), and (5). It can be easily shown that problem P is convex programming. Moreover, the objective function is strictly concave with respect to \\bar{x}_i, the scheduling decision of any customer i, when the other customers' scheduling decisions, \\bar{x}_{-i}=[\\bar{x}_{i'}]_{i'\\ne i}, are fixed. Due to these properties of problem P, we can use the Gauss-Seidel method to solve it [22]."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"At each iteration k+1, customers update there energy scheduling decisions, \\bar{x}_i^{(k+1)}, sequentially by solving the following problem: P1_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(x_{i,Tot}^t+X_{-i}^{t,(k+1)}) s.t. \\bar{x}_i\\in X_i, where X_{-i}^{t,(k+1)}=\\sum_{i'\u003ci}x_{i',Tot}^{t,(k+1)}+\\sum_{i'>i}x_{i',Tot}^{t,(k)}. Problem P1_i is a convex optimization problem and can be solved by using standard algorithms for convex optimization.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R001","quote":"At each iteration k+1, customers update there energy scheduling decisions, \\bar{x}_i^{(k+1)}, sequentially by solving the following problem: P1_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(x_{i,Tot}^t+X_{-i}^{t,(k+1)}) s.t. \\bar{x}_i\\in X_i, where X_{-i}^{t,(k+1)}=\\sum_{i'\u003ci}x_{i',Tot}^{t,(k+1)}+\\sum_{i'>i}x_{i',Tot}^{t,(k)}. Problem P1_i is a convex optimization problem and can be solved by using standard algorithms for convex optimization."},{"evidence_id":"v141-b-g02-e04","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"1222","section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R001","quote":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-54c42059a7-p04-c2r1__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"JOURNAL ON SELECTED AREAS IN COMMUNICATIONS, VOL. 31, NO. 7, JULY 2013 we following problem: as P2i ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9) and function C'^t(z) denotes the first derivative of the total cost function C^t(z) with respect to z. Proof: See Appendix.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R001","quote":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9) and function C'^t(z) denotes the first derivative of the total cost function C^t(z) with respect to z. Proof: See Appendix."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-54c42059a7-p04-c2r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"ch and function C ′t(z) denotes the ﬁrst derivative of the totaltal cost function Ct(z) with respect","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R001","quote":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-54c42059a7-p04-c2r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"ch and function C ′t(z) denotes the ﬁrst derivative of the totaltal cost function Ct(z) with respect","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R003","quote":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot."},{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-54c42059a7-p04-c2r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of how much energy the customers consume. However, itm should be noted that the optimal electricity ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"According to Proposition 2, the linear billing scheme always guarantees that the aggregator can make a profit regardless of how much energy the customers consume. However, it should be noted that the optimal electricity rates, \\bar{\\pi}^*, are determined only focusing on maximizing the social welfare without consideration on how we distribute the total cost to customers and the aggregator. Moreover, the linear electricity rates, \\bar{\\pi}^*, which are identically applied to all the customers, can result in unfairness among customers with different energy consumption levels. The unfairness issue can be explained as follows. Since the wholesale price, p^t(\\sum_{i\\in I}x_{i,Tot}^{*t}), increases as the total demand at time-slot t, \\sum_{i\\in I}x_{i,Tot}^{*t}, increases, the optimal electricity rate, \\pi^{*t}, also increases as \\sum_{i\\in I}x_{i,Tot}^{*t} increases as shown in (9). Hence, the presence of heavy customers with a large energy consumption drives up the electricity rates, which is unfair to light customers. In the next section, we shall take into consideration the cost allocation and unfairness issues for a non-collaborative scenario.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R003","quote":"According to Proposition 2, the linear billing scheme always guarantees that the aggregator can make a profit regardless of how much energy the customers consume. However, it should be noted that the optimal electricity rates, \\bar{\\pi}^*, are determined only focusing on maximizing the social welfare without consideration on how we distribute the total cost to customers and the aggregator. Moreover, the linear electricity rates, \\bar{\\pi}^*, which are identically applied to all the customers, can result in unfairness among customers with different energy consumption levels. The unfairness issue can be explained as follows. Since the wholesale price, p^t(\\sum_{i\\in I}x_{i,Tot}^{*t}), increases as the total demand at time-slot t, \\sum_{i\\in I}x_{i,Tot}^{*t}, increases, the optimal electricity rate, \\pi^{*t}, also increases as \\sum_{i\\in I}x_{i,Tot}^{*t} increases as shown in (9). Hence, the presence of heavy customers with a large energy consumption drives up the electricity rates, which is unfair to light customers. In the next section, we shall take into consideration the cost allocation and unfairness issues for a non-collaborative scenario."},{"evidence_id":"v141-b-g02-e04","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"1222","section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R003","quote":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-54c42059a7-p04-c2r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"ch and function C ′t(z) denotes the ﬁrst derivative of the totaltal cost function Ct(z) with respect","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R005","quote":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot."},{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-54c42059a7-p04-c2r3__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"y g q ng aggregator has to pay to the utility company. es Proof: Comparing the total cost function i","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Proposition 2. The sum of bills charged to all customers calculated based on the linear rate \\bar{\\pi}^* in problem P2_i, is always larger than or equal to the total cost which the aggregator has to pay to the utility company. Proof: Comparing the total cost function in (7) and the sum of bills based on the linear rate in (9), we can conclude that the following inequality is always true. \\sum_{t\\in T}\\pi^{*t}\\sum_{i\\in I}x_{i,Tot}^{*t}=\\sum_{t\\in T}C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})\\sum_{i\\in I}x_{i,Tot}^{*t}=\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^{*t})+\\sum_{t\\in T}a^t(\\sum_{i\\in I}x_{i,Tot}^{*t})^2\\ge\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^{*t}). (10)","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R005","quote":"Proposition 2. The sum of bills charged to all customers calculated based on the linear rate \\bar{\\pi}^* in problem P2_i, is always larger than or equal to the total cost which the aggregator has to pay to the utility company. Proof: Comparing the total cost function in (7) and the sum of bills based on the linear rate in (9), we can conclude that the following inequality is always true. \\sum_{t\\in T}\\pi^{*t}\\sum_{i\\in I}x_{i,Tot}^{*t}=\\sum_{t\\in T}C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})\\sum_{i\\in I}x_{i,Tot}^{*t}=\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^{*t})+\\sum_{t\\in T}a^t(\\sum_{i\\in I}x_{i,Tot}^{*t})^2\\ge\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^{*t}). (10)"},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-54c42059a7-p04-c2r1__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"JOURNAL ON SELECTED AREAS IN COMMUNICATIONS, VOL. 31, NO. 7, JULY 2013 we following problem: as P2i ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9) and function C'^t(z) denotes the first derivative of the total cost function C^t(z) with respect to z. Proof: See Appendix.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R005","quote":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9) and function C'^t(z) denotes the first derivative of the total cost function C^t(z) with respect to z. Proof: See Appendix."},{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-54c42059a7-p03-c2r4__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"re 2 tricity market as illustrated in Fig. 1. The utility company charges the aggregator an electric","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"For each time-slot, the aggregator buys electricity, which corresponds to the total demand of the power system, \\sum_{i\\in I}x_{i,Tot}^t, from the utility company in the wholesale electricity market as illustrated in Fig. 1. The utility company charges the aggregator an electricity cost based on a linear wholesale electricity price function per unit energy [21], which is given by p^t(\\sum_{i\\in I}x_{i,Tot}^t)=a^t\\sum_{i\\in I}x_{i,Tot}^t+b^t, \\forall t\\in T, (6) where a^t>0 and b^t>0 may vary in time and are predetermined by the utility company before the scheduling interval.","paper":"38-bidirectional_ev_trading","rule_id":"v141-c-R005","quote":"For each time-slot, the aggregator buys electricity, which corresponds to the total demand of the power system, \\sum_{i\\in I}x_{i,Tot}^t, from the utility company in the wholesale electricity market as illustrated in Fig. 1. The utility company charges the aggregator an electricity cost based on a linear wholesale electricity price function per unit energy [21], which is given by p^t(\\sum_{i\\in I}x_{i,Tot}^t)=a^t\\sum_{i\\in I}x_{i,Tot}^t+b^t, \\forall t\\in T, (6) where a^t>0 and b^t>0 may vary in time and are predetermined by the utility company before the scheduling interval."}],"candidate_only":true,"classification_subtypes":["wholesale_price_and_marginal_cost_tariff"],"projection_statuses":["composite"],"taxonomy":{"primary_family":"kind-L6-345232b592","secondary_families":[],"stage":"L6","ontological_kind":"wholesale_price_and_marginal_cost_tariff"},"semantic_definition":{},"source_units":[{"unit_id":"38-bidirectional_ev_trading::M01::coordination.price_signal","paper_id":"38-bidirectional_ev_trading","mechanism_id":"M01","function":"coordination.price_signal","source_occurrences":[{"id":"38-bidirectional_ev_trading::v141-c-R001::V::coordination.price_signal","rule_id":"v141-c-R001","market_meaning":"Wholesale price-function information provides an input to customers' sequential social-welfare scheduling updates. The aggregator can broadcast that information together with other customers' aggregate energy consumption. Scope: Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i. Condition: At each iteration; the information can be broadcast at the beginning of the iteration. The common-linear-rate distributed formulation represents the collaborative social-welfare-optimal schedule as a collection of customer-optimal schedules at the specified rates. Scope: Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. Condition: Electricity rates equal marginal total cost evaluated at the social-welfare-optimal aggregate consumption, as specified in (9). Collaborative scheduling maximizes the sum of all customers' utilities minus the total cost charged to the aggregator, subject to each customer's feasible scheduling set satisfying conditions (1), (2), (3), and (5). Scope: Collaborative power system, all customers, over the scheduling interval. Condition: All customers are willing to cooperate.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Collaborative power system, all customers, over the scheduling interval. | Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. | Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E12","v141-b-g01-E13","v141-b-g01-E14","v141-b-g02-e04"]},"constraint_refs":["38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C001","38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C002"],"decision_anchor":"clearing.social_welfare","source_rule_sha256":"99d94280c77d2e63e3f40c3714f72118aa2227f73ec9a54b8a4c1392f400d7cd"},{"id":"38-bidirectional_ev_trading::v141-c-R003::V::coordination.price_signal","rule_id":"v141-c-R003","market_meaning":"The aggregator sets and applies electricity rates to coordinate customers' decentralized, utility-maximizing energy schedules. Scope: Collaborative distributed energy scheduling under the linear billing scheme represented by problems P2_i. The coordinating electricity rates are identical across customers and are determined solely to maximize social welfare, without considering allocation of total cost between customers and the aggregator. Scope: Collaborative linear billing with optimal electricity rates. Each customer's distributed scheduling iteration needs only the wholesale price function and the sum of other customers' energy consumption for every time-slot. Scope: Each iteration of the collaborative Gauss-Seidel distributed scheduling algorithm.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Collaborative distributed energy scheduling under the linear billing scheme represented by problems P2_i. | Collaborative linear billing with optimal electricity rates. | Each iteration of the collaborative Gauss-Seidel distributed scheduling algorithm.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E14","v141-b-g01-E16","v141-b-g02-e04"]},"constraint_refs":["38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C001","38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C002","38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C003"],"decision_anchor":"coordination.price_signal","source_rule_sha256":"b4b4026b6aad73e4914556f866f94bbb582159c533b07a51b37ed023e5beccd9"},{"id":"38-bidirectional_ev_trading::v141-c-R005::V::coordination.price_signal","rule_id":"v141-c-R005","market_meaning":"The coordinating aggregator charges each customer an electricity bill for each time-slot. Scope: Customer billing in the collaborative distributed energy-scheduling framework. The electricity-rate signal coordinating distributed customer scheduling supplies the rate used to calculate customer bills. Scope: Customer bills under the collaborative linear billing scheme. Condition: The optimal linear electricity rates of problem P2_i are applied. The aggregator has an obligation to pay the utility company its electricity procurement cost. Scope: The aggregator's wholesale electricity procurement supporting the collaborative customer system. The sum of customer bills is greater than or equal to the total cost payable by the aggregator to the utility company. Scope: Aggregate customer bills and the aggregator's utility-company cost under collaborative linear billing. Condition: Bills are calculated using the linear rate bar-pi* in problem P2_i.","omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Aggregate customer bills and the aggregator's utility-company cost under collaborative linear billing. | Customer billing in the collaborative distributed energy-scheduling framework. | Customer bills under the collaborative linear billing scheme. | The aggregator's wholesale electricity procurement supporting the collaborative customer system.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E01","v141-b-g01-E14","v141-b-g01-E15","v141-b-g02-e04"]},"constraint_refs":["38-bidirectional_ev_trading::v141-c-R005::v141-c-R005-C002"],"decision_anchor":"settlement.payment","source_rule_sha256":"e1fa878d9ee1010543318756811ec7525744882978a94e702f9adaba64cf5852"}],"constraints":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"Wholesale price-function information provides an input to customers' sequential social-welfare scheduling updates. The aggregator can broadcast that information together with other customers' aggregate energy consumption. Scope: Sequential distributed solution of the collaborative scheduling problem using customer subproblems P1_i. Condition: At each iteration; the information can be broadcast at the beginning of the iteration.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","clearing.social_welfare"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E12","v141-b-g02-e04"],"ref":"38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C001","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-54c42059a7-p04-c1r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"cooperate to maximize the social welfare of the system, which anis deﬁned as the sum of all customer","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"In this section, we study the energy scheduling problem for a collaborative system, where all customers are willing to cooperate to maximize the social welfare of the system, which is defined as the sum of all customers' utilities minus the total cost charged to the aggregator. The resulting social welfare serves an upper bound on social welfare obtained using any feasible approaches. We first consider the following social welfare maximization problem: P: \\max_{\\bar{x}} \\sum_{t\\in T}\\sum_{i\\in I}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^t) s.t. \\bar{x}_i\\in X_i, \\forall i\\in I, where X_i represents the feasible set of customer i's energy scheduling which is defined as a set of \\bar{x}_i's that satisfy conditions in (1),(2),(3), and (5). It can be easily shown that problem P is convex programming. Moreover, the objective function is strictly concave with respect to \\bar{x}_i, the scheduling decision of any customer i, when the other customers' scheduling decisions, \\bar{x}_{-i}=[\\bar{x}_{i'}]_{i'\\ne i}, are fixed. Due to these properties of problem P, we can use the Gauss-Seidel method to solve it [22]."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"At each iteration k+1, customers update there energy scheduling decisions, \\bar{x}_i^{(k+1)}, sequentially by solving the following problem: P1_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}C^t(x_{i,Tot}^t+X_{-i}^{t,(k+1)}) s.t. \\bar{x}_i\\in X_i, where X_{-i}^{t,(k+1)}=\\sum_{i'\u003ci}x_{i',Tot}^{t,(k+1)}+\\sum_{i'>i}x_{i',Tot}^{t,(k)}. Problem P1_i is a convex optimization problem and can be solved by using standard algorithms for convex optimization."},{"evidence_id":"v141-b-g02-e04","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"1222","section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration."}]},{"constraint_id":"v141-c-R001-C002","kind":"mathematical","role":"core","statement":"The common-linear-rate distributed formulation represents the collaborative social-welfare-optimal schedule as a collection of customer-optimal schedules at the specified rates. Scope: Proposition 1's distributed linear-billing representation of the collaborative optimum, applying common time-slot rates to all customers. Condition: Electricity rates equal marginal total cost evaluated at the social-welfare-optimal aggregate consumption, as specified in (9).","expression":"P2_i:\\ \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*,t}x_{i,Tot}^t\\quad \\text{s.t. }\\bar{x}_i\\in X_i,\\quad \\pi^{*,t}=C'^t\\left(\\sum_{i\\in I}x_{i,Tot}^{*,t}\\right)=2a^t\\sum_{i\\in I}x_{i,Tot}^{*,t}+b^t,\\ \\forall t\\in T","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","clearing.social_welfare"],"variable_refs":["v141-c-R001-x-app","v141-c-R001-x-tot","v141-c-R001-x-pi"],"parameter_refs":["v141-c-R001-theta-U","v141-c-R001-theta-C","v141-c-R001-theta-a","v141-c-R001-theta-b"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E14"],"ref":"38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C002","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-54c42059a7-p04-c2r1__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"JOURNAL ON SELECTED AREAS IN COMMUNICATIONS, VOL. 31, NO. 7, JULY 2013 we following problem: as P2i ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9) and function C'^t(z) denotes the first derivative of the total cost function C^t(z) with respect to z. Proof: See Appendix."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-54c42059a7-p04-c2r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"ch and function C ′t(z) denotes the ﬁrst derivative of the totaltal cost function Ct(z) with respect","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot."}]},{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"The aggregator sets and applies electricity rates to coordinate customers' decentralized, utility-maximizing energy schedules. Scope: Collaborative distributed energy scheduling under the linear billing scheme represented by problems P2_i.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E14"],"ref":"38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C001","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-54c42059a7-p04-c2r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"ch and function C ′t(z) denotes the ﬁrst derivative of the totaltal cost function Ct(z) with respect","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot."}]},{"constraint_id":"v141-c-R003-C002","kind":"procedural","role":"core","statement":"The coordinating electricity rates are identical across customers and are determined solely to maximize social welfare, without considering allocation of total cost between customers and the aggregator. Scope: Collaborative linear billing with optimal electricity rates.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E16"],"ref":"38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C002","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-54c42059a7-p04-c2r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of how much energy the customers consume. However, itm should be noted that the optimal electricity ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"According to Proposition 2, the linear billing scheme always guarantees that the aggregator can make a profit regardless of how much energy the customers consume. However, it should be noted that the optimal electricity rates, \\bar{\\pi}^*, are determined only focusing on maximizing the social welfare without consideration on how we distribute the total cost to customers and the aggregator. Moreover, the linear electricity rates, \\bar{\\pi}^*, which are identically applied to all the customers, can result in unfairness among customers with different energy consumption levels. The unfairness issue can be explained as follows. Since the wholesale price, p^t(\\sum_{i\\in I}x_{i,Tot}^{*t}), increases as the total demand at time-slot t, \\sum_{i\\in I}x_{i,Tot}^{*t}, increases, the optimal electricity rate, \\pi^{*t}, also increases as \\sum_{i\\in I}x_{i,Tot}^{*t} increases as shown in (9). Hence, the presence of heavy customers with a large energy consumption drives up the electricity rates, which is unfair to light customers. In the next section, we shall take into consideration the cost allocation and unfairness issues for a non-collaborative scenario."}]},{"constraint_id":"v141-c-R003-C003","kind":"procedural","role":"core","statement":"Each customer's distributed scheduling iteration needs only the wholesale price function and the sum of other customers' energy consumption for every time-slot. Scope: Each iteration of the collaborative Gauss-Seidel distributed scheduling algorithm.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e04"],"ref":"38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C003","source_rule_id":"v141-c-R003","evidence":[{"evidence_id":"v141-b-g02-e04","location":{"location_id":"src-54c42059a7-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"1222","section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"of where Xt,(k+1)−i = i′\u003ci xt,(k+1)i′,T ot + i′>i xt,(k)i′,T ot. Problem sh P1i is a convex optimiza","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Note that at each iteration, each customer needs to acquire only the information about the wholesale price function p^t(\\cdot), \\forall t\\in T and the sum energy consumption of other customers, X_{-i}^{t,(k+1)}, \\forall t\\in T. Such information can be updated and broadcast by the aggregator through the communication with the customer's ECS at the beging of each iteration."}]},{"constraint_id":"v141-c-R005-C002","kind":"mathematical","role":"core","statement":"The electricity-rate signal coordinating distributed customer scheduling supplies the rate used to calculate customer bills. Scope: Customer bills under the collaborative linear billing scheme. Condition: The optimal linear electricity rates of problem P2_i are applied.","expression":"\\pi^{*t}=C'^t\\left(\\sum_{i\\in I}x_{i,Tot}^{*t}\\right)=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\quad \\forall t\\in T","formalization_origin":"source","template_id":null,"members":["coordination.price_signal","settlement.payment"],"variable_refs":["v141-c-R005-x-i-tot-star"],"parameter_refs":["v141-c-R005-theta-pi-star-t","v141-c-R005-theta-a-t","v141-c-R005-theta-b-t"],"evidence_ids":["v141-b-g01-E14","v141-b-g01-E15","v141-b-g01-E13","v141-b-g01-E07"],"ref":"38-bidirectional_ev_trading::v141-c-R005::v141-c-R005-C002","source_rule_id":"v141-c-R005","evidence":[{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-54c42059a7-p04-c2r2__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"ch and function C ′t(z) denotes the ﬁrst derivative of the totaltal cost function Ct(z) with respect","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"From Proposition 1, we can interpret problem P2_i, \\forall i\\in I as a distributed energy scheduling framework based on a linear billing scheme where the aggregator decides the electricity rates \\bar{\\pi}^*=[\\pi^{*t}]_{\\forall t\\in T}, and apply these electricity rates to all customers. Then, each customer i decides its own energy scheduling to maximize its own utility by solving problem P2_i. The aggregator charges each customer an electricity bill according to the announced electricity rates and the amount of energy consumption at each time-slot."},{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-54c42059a7-p04-c2r3__v141-a-M01-settlement","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"y g q ng aggregator has to pay to the utility company. es Proof: Comparing the total cost function i","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Proposition 2. The sum of bills charged to all customers calculated based on the linear rate \\bar{\\pi}^* in problem P2_i, is always larger than or equal to the total cost which the aggregator has to pay to the utility company. Proof: Comparing the total cost function in (7) and the sum of bills based on the linear rate in (9), we can conclude that the following inequality is always true. \\sum_{t\\in T}\\pi^{*t}\\sum_{i\\in I}x_{i,Tot}^{*t}=\\sum_{t\\in T}C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})\\sum_{i\\in I}x_{i,Tot}^{*t}=\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^{*t})+\\sum_{t\\in T}a^t(\\sum_{i\\in I}x_{i,Tot}^{*t})^2\\ge\\sum_{t\\in T}C^t(\\sum_{i\\in I}x_{i,Tot}^{*t}). (10)"},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-54c42059a7-p04-c2r1__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III. Energy Scheduling: Collaborative Approach","anchor_text":"JOURNAL ON SELECTED AREAS IN COMMUNICATIONS, VOL. 31, NO. 7, JULY 2013 we following problem: as P2i ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Proposition 1. The optimal solution of problem P, \\bar{x}^*, can be represented as the collection of optimal solutions of the following problem: P2_i \\max_{\\bar{x}_i}\\sum_{t\\in T}U_i^t(x_{i,App}^t)-\\sum_{t\\in T}\\pi^{*t}x_{i,Tot}^t s.t. \\bar{x}_i\\in X_i, where \\bar{\\pi}^*=[\\pi^{*t}]_{t\\in T} is given as \\pi^{*t}=C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t})=2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t, \\forall t\\in T, (9) and function C'^t(z) denotes the first derivative of the total cost function C^t(z) with respect to z. Proof: See Appendix."},{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-54c42059a7-p03-c2r4__v141-a-M01-clearing","page":3,"printed_page":null,"section":"II. System Model","anchor_text":"re 2 tricity market as illustrated in Fig. 1. The utility company charges the aggregator an electric","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"For each time-slot, the aggregator buys electricity, which corresponds to the total demand of the power system, \\sum_{i\\in I}x_{i,Tot}^t, from the utility company in the wholesale electricity market as illustrated in Fig. 1. The utility company charges the aggregator an electricity cost based on a linear wholesale electricity price function per unit energy [21], which is given by p^t(\\sum_{i\\in I}x_{i,Tot}^t)=a^t\\sum_{i\\in I}x_{i,Tot}^t+b^t, \\forall t\\in T, (6) where a^t>0 and b^t>0 may vary in time and are predetermined by the utility company before the scheduling interval."}]}],"variables":[{"variable_id":"v141-c-R001-x-app","symbol":"x_{i,App}^t","meaning":"Energy consumed by customer i's residential appliances during time-slot t.","kind":"operational","domain":"Real-valued energy quantity constrained by x_{i,App}^{min,t} \u003c= x_{i,App}^t \u003c= x_{i,App}^{max,t} and by the customer's feasible set X_i.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E04","v141-b-g01-E10"],"source_rule_id":"v141-c-R001","declaration_ref":"38-bidirectional_ev_trading::v141-c-R001::x::v141-c-R001-x-app"},{"variable_id":"v141-c-R001-x-tot","symbol":"x_{i,Tot}^t","meaning":"Total energy consumption of customer i during time-slot t, including residential appliances and the EV; negative values correspond to energy sold to the aggregator.","kind":"operational","domain":"Real-valued energy quantity constrained by (2)-(3), (5), and X_i; may be negative when a Type III EV sells stored energy.","unit":"kWh","indices":["i","t"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E03","v141-b-g01-E04","v141-b-g01-E10"],"source_rule_id":"v141-c-R001","declaration_ref":"38-bidirectional_ev_trading::v141-c-R001::x::v141-c-R001-x-tot"},{"variable_id":"v141-c-R001-x-pi","symbol":"\\pi^{*,t}","meaning":"Common linear electricity rate for time-slot t, set equal to marginal total cost evaluated at the social-welfare-optimal aggregate consumption.","kind":"operational","domain":"Real-valued rate given by equation (9) at the social-welfare optimum.","unit":"$/kWh","indices":["t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E14"],"source_rule_id":"v141-c-R001","declaration_ref":"38-bidirectional_ev_trading::v141-c-R001::x::v141-c-R001-x-pi"},{"variable_id":"v141-c-R005-x-i-tot-star","symbol":"x_{i,Tot}^{*t}","meaning":"Optimal total energy consumption of customer i during time-slot t in the collaborative linear-billing schedule; this is the billed energy quantity. A negative value represents energy sold to the aggregator when such trading is permitted.","kind":"operational","domain":"Real-valued energy quantity; the source allows individual total energy to be negative for sales, while aggregate system demand is assumed nonnegative.","unit":"kWh","indices":["i in I","t in T"],"evidence_ids":["v141-b-g01-E01","v141-b-g01-E02","v141-b-g01-E03","v141-b-g01-E08","v141-b-g01-E14","v141-b-g01-E15"],"source_rule_id":"v141-c-R005","declaration_ref":"38-bidirectional_ev_trading::v141-c-R005::x::v141-c-R005-x-i-tot-star"}],"parameters":[{"parameter_id":"v141-c-R001-theta-U","symbol":"U_i^t(\\cdot)","meaning":"Customer i's increasing concave utility function for residential appliance energy consumption during time-slot t.","value":{"kind":"symbolic","number_value":null,"text_value":"increasing concave function"},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E10"],"source_rule_id":"v141-c-R001","declaration_ref":"38-bidirectional_ev_trading::v141-c-R001::theta::v141-c-R001-theta-U"},{"parameter_id":"v141-c-R001-theta-C","symbol":"C^t(\\cdot)","meaning":"Aggregator's total cost at time-slot t as a function of total customer energy consumption.","value":{"kind":"symbolic","number_value":null,"text_value":"C^t(z)=p^t(z)z"},"unit":"$","indices":["t"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10","v141-b-g01-E13"],"source_rule_id":"v141-c-R001","declaration_ref":"38-bidirectional_ev_trading::v141-c-R001::theta::v141-c-R001-theta-C"},{"parameter_id":"v141-c-R001-theta-a","symbol":"a^t","meaning":"Time-varying positive slope coefficient of the linear wholesale price function.","value":{"kind":"symbolic","number_value":null,"text_value":"positive time-varying coefficient predetermined by the utility company"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E13"],"source_rule_id":"v141-c-R001","declaration_ref":"38-bidirectional_ev_trading::v141-c-R001::theta::v141-c-R001-theta-a"},{"parameter_id":"v141-c-R001-theta-b","symbol":"b^t","meaning":"Time-varying positive intercept coefficient of the linear wholesale price function.","value":{"kind":"symbolic","number_value":null,"text_value":"positive time-varying coefficient predetermined by the utility company"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E13"],"source_rule_id":"v141-c-R001","declaration_ref":"38-bidirectional_ev_trading::v141-c-R001::theta::v141-c-R001-theta-b"},{"parameter_id":"v141-c-R005-theta-pi-star-t","symbol":"\\pi^{*t}","meaning":"Optimal linear electricity rate at time-slot t under the collaborative linear billing scheme, applied identically to all customers and used to calculate each bill.","value":{"kind":"symbolic","number_value":null,"text_value":"C'^t(\\sum_{i\\in I}x_{i,Tot}^{*t}) = 2a^t\\sum_{i\\in I}x_{i,Tot}^{*t}+b^t"},"unit":"$/kWh","indices":["t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E14","v141-b-g01-E15"],"source_rule_id":"v141-c-R005","declaration_ref":"38-bidirectional_ev_trading::v141-c-R005::theta::v141-c-R005-theta-pi-star-t"},{"parameter_id":"v141-c-R005-theta-a-t","symbol":"a^t","meaning":"Time-varying positive coefficient of the linear wholesale electricity price function, predetermined by the utility company before the scheduling interval.","value":{"kind":"symbolic","number_value":null,"text_value":"a^t > 0"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E09","v141-b-g01-E15"],"source_rule_id":"v141-c-R005","declaration_ref":"38-bidirectional_ev_trading::v141-c-R005::theta::v141-c-R005-theta-a-t"},{"parameter_id":"v141-c-R005-theta-b-t","symbol":"b^t","meaning":"Time-varying positive constant term of the linear wholesale electricity price function, predetermined by the utility company before the scheduling interval.","value":{"kind":"symbolic","number_value":null,"text_value":"b^t > 0"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E07","v141-b-g01-E09","v141-b-g01-E15"],"source_rule_id":"v141-c-R005","declaration_ref":"38-bidirectional_ev_trading::v141-c-R005::theta::v141-c-R005-theta-b-t"}]}],"source_definitions":[{"unit_id":"38-bidirectional_ev_trading::M01::coordination.price_signal","stage":"L6","subtype":"wholesale_price_and_marginal_cost_tariff","projection_status":"composite","target_definition":"This unit contains two types of prices: information used for iteration, p^t(Q)=a^tQ+b^t; and the uniform customer rate, π^{*,t}=C'^t(Q*)=2a^tQ*+b^t, where Q*=Σ_i x_{i,Tot}^{*,t} is the welfare-optimal total energy use.","form_kind":"mathematical","identity_fields":["Object: two price objects, the wholesale price function and the uniform customer rate","Core relation: the wholesale function provides price information; the customer rate is determined by the marginal total cost at the optimum","Output: wholesale price information and the customer rate commonly applicable in each time period"],"variation_fields":["The wholesale function coefficients are predetermined by the utility and vary by time period","Wholesale price information is used for iteration together with the aggregate energy use of other customers","The uniform rate is used for dispatch and billing, and when it is determined, only the welfare objective is considered"],"constraint_refs":["38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C001","38-bidirectional_ev_trading::v141-c-R001::v141-c-R001-C002","38-bidirectional_ev_trading::v141-c-R003::v141-c-R003-C003","38-bidirectional_ev_trading::v141-c-R005::v141-c-R005-C002"],"paper_id":"38-bidirectional_ev_trading","mechanism_id":"M01","function":"coordination.price_signal","template_code":"JOC"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/148"});
